import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G)); print(G['Demo pair 1 input'])
print([r for r in G['Demo pair 1 output']][:3])

import json
def transform(g):
    w=len(g[0]); s=g[0].index(2); H=w
    out=[[0]*w for _ in range(H)]
    # 2-rays
    for r in range(s+1):
        for c in (s-r, s+r):
            if 0<=c<w: out[r][c]=2
    # 1-rays: emitters on left-ray line at even rows r_e>=2 (incl. virtual beyond wall)
    for r_e in range(2, 2*H, 2):
        d = 2*r_e - s          # r-c of emitted down-right ray
        for r in range(r_e+1, H):
            c = r - d
            if 0<=c<w and out[r][c]==0: out[r][c]=1
    return out
ok = transform(G['Demo pair 1 input'])==G['Demo pair 1 output']
print("demo match:", ok)
if not ok:
    a=transform(G['Demo pair 1 input']); b=G['Demo pair 1 output']
    for r in range(len(b)):
        if a[r]!=b[r]: print(r,a[r],b[r])
out = transform(G['Test input'])
print(json.dumps(out))
